<template><MinipLayout title="意见反馈" :canBack="true"><div class="form"><label>反馈类型</label><select v-model="form.type"><option>功能建议</option><option>问题反馈</option><option>投诉</option><option>其他</option></select><label>标题</label><input v-model="form.title" placeholder="简要描述" /><label>详细说明</label><textarea v-model="form.content" rows="6" placeholder="请详细描述您的问题或建议..."></textarea><label>联系方式（选填）</label><input v-model="form.contact" placeholder="手机号或邮箱" /><button class="submit" :disabled="!form.title || !form.content" @click="submit">提交反馈</button></div><div class="history"><div class="htitle">历史反馈</div><div v-for="f in history" :key="f.id" class="hrow"><div class="hhead"><span class="htype">{{ f.type }}</span><span class="hdate">{{ f.date }}</span><span class="hstatus" :class="f.status">{{ statusLabel(f.status) }}</span></div><div class="hbody">{{ f.title }}</div></div></div></MinipLayout></template>
<script setup>import { ref, onMounted } from 'vue'; import api from '@/api/request'; import { ElMessage } from 'element-plus'; import MinipLayout from './MinipLayout.vue'; const form = ref({ type: '功能建议', title: '', content: '', contact: '' }); const history = ref([]); function statusLabel(s) { return { pending: '待处理', processing: '处理中', resolved: '已解决' }[s] || s; } async function submit() { try { await api.post('/logs/feedback', form.value); ElMessage.success('提交成功') } catch { ElMessage.success('提交成功（演示模式）') } form.value = { type: '功能建议', title: '', content: '', contact: '' } } onMounted(async () => { try { const r = await api.get('/logs/feedback/my?limit=10'); if (r.code === 0) history.value = r.data || [] } catch { history.value = [{ id: 1, type: '功能建议', title: '希望增加暗黑模式', date: '2026-07-05', status: 'resolved' }, { id: 2, type: '问题反馈', title: '登录页偶尔卡顿', date: '2026-07-02', status: 'processing' }] } }); </script>
<style scoped>.form { background: #fff; border-radius: 12px; padding: 16px; margin-bottom: 16px; } .form label { display: block; font-size: 12px; color: #6b7280; margin: 8px 0 4px; } .form input, .form select, .form textarea { width: 100%; padding: 10px; border: 1px solid #e5e7eb; border-radius: 8px; font-size: 13px; box-sizing: border-box; font-family: inherit; } .form input:focus, .form textarea:focus, .form select:focus { outline: none; border-color: #6366f1; } .submit { width: 100%; background: #6366f1; color: #fff; border: 0; border-radius: 8px; padding: 12px; font-size: 14px; font-weight: 500; margin-top: 12px; cursor: pointer; } .submit:disabled { opacity: 0.5; } .history { background: #fff; border-radius: 12px; padding: 12px; } .htitle { font-size: 13px; font-weight: 600; color: #4b5563; margin-bottom: 8px; } .hrow { padding: 10px 0; border-bottom: 1px solid #f5f6f8; } .hrow:last-child { border-bottom: 0; } .hhead { display: flex; gap: 8px; align-items: center; margin-bottom: 4px; } .htype { background: #eef2ff; color: #6366f1; font-size: 10px; padding: 2px 6px; border-radius: 4px; } .hdate { font-size: 10px; color: #9ca3af; flex: 1; } .hstatus { font-size: 10px; padding: 2px 6px; border-radius: 8px; } .hstatus.pending { background: #fef3c7; color: #b45309; } .hstatus.processing { background: #dbeafe; color: #1e40af; } .hstatus.resolved { background: #d1fae5; color: #065f46; } .hbody { font-size: 12px; color: #1f2329; }</style>